{"command":"cat <<'EOF' > src/main.rs
use clap::Parser;
use std::io::{self, BufRead};
use std::process::{Command, Stdio};
use std::path::PathBuf;

#[derive(Parser, Debug)]
#[command(name = "delta", version = "0.18.2", about = "A viewer for git and diff output")]
struct Args {
    #[arg(help = "First file to be compared when delta is being used to diff two files.")]
    minus_file: Option<PathBuf>,

    #[arg(help = "Second file to be compared when delta is being used to diff two files.")]
    plus_file: Option<PathBuf>,

    #[arg(long, help = "Display line numbers.")]
    line_numbers: bool,

    #[arg(long, help = "Display side-by-side view.")]
    side_by_side: bool,

    // Add more options as needed
}

fn main() -> io::Result<()> {
    let args = Args::parse();

    if let (Some(file1), Some(file2)) = (args.minus_file, args.plus_file) {
        let output = Command::new("diff")
            .arg("-u")
            .arg(file1)
            .arg(file2)
            .stdout(Stdio::piped())
            .spawn()?
            .stdout
            .expect("Failed to open diff stdout");

        process_input(io::BufReader::new(output), &args)
    } else {
        process_input(io::BufReader::new(io::stdin()), &args)
    }
}

fn process_input<R: BufRead>(reader: R, _args: &Args) -> io::Result<()> {
    for line in reader.lines() {
        println!("{}", line?);
    }
    Ok(())
}
EOF
./compile.sh
"}

